<template>
  <view class="pilot">
    <view class="top"><view class="brand"><view class="brand-icon"><text></text><text></text></view><view><view class="brand-name">{{ $t("app.name") }}</view><view class="brand-caption">PLAYER MATCH</view></view></view><view class="top-utilities"><language-switch/><text class="badge"><text class="live-indicator">●</text> {{ $t("ui.operations_duos") }}</text></view></view>
    <view class="tabs"><button v-for="item in PILOT_TABS" :key="item.id" :class="{active:tab===item.id}" :aria-pressed="tab===item.id" @click="switchTab(item.id)"><text>{{$t(item.label)}}</text><text v-if="item.id===PILOT_TAB.HALL && state.ticket?.status==='waiting'" class="recruiting-badge" role="status">{{ $t("status.recruiting") }}</text></button></view>
    <growth-tools ref="growthRef" :ticket="state.ticket" :active-ticket="activeTicket" :activities-visible="tab===PILOT_TAB.ACTIVITIES" @matched="applySharedMatch" @edit="tab=PILOT_TAB.CONDITIONS" @activity="applyActivity"/>
    <view v-if="error" class="error" role="alert">{{$error(error)}}</view><view v-if="state.notice && tab!==PILOT_TAB.HALL && tab!==PILOT_TAB.ACTIVITIES" class="status-strip">{{$t(state.notice)}}</view><view v-if="state.squad?.status==='proposed' && tab!==PILOT_TAB.MY_RECRUITMENT && tab!==PILOT_TAB.ACTIVITIES" class="status-strip pending">{{$t('message.pendingConfirmation',{seconds:confirmRemaining})}}<button class="status-link" @click="switchTab(PILOT_TAB.MY_RECRUITMENT)">{{ $t("ui.view_session_agreement") }}</button></view>
    <recruitment-wizard ref="wizardRef" v-if="tab===PILOT_TAB.CONDITIONS" :busy="busy" :active-ticket="activeTicket" :existing-ticket="state.ticket" :squad-status="state.squad?.status" :resume-draft="wizardDraft" :submit-error="error" :import-profile="testImport" @clear-error="error=''" @view-active="switchTab(PILOT_TAB.MY_RECRUITMENT)" @draft-change="wizardDraft=$event" @replace="replaceRecruitment" @submit="join"/>
    <view v-if="tab===PILOT_TAB.HALL">
      <view v-if="state.ticket && !['waiting','expired'].includes(state.ticket.status)" class="status-strip"><text class="status-dot" :class="{online:activeTicket}"/><text>{{!activeTicket?(state.ticket.status==='expired'?$t("ui.your_listing_expired_publish_again_to_apply_for_a"):$t("ui.publish_your_conditions_before_applying")):$t("ui.a_teammate_is_awaiting_confirmation")}}</text><button v-if="!activeTicket" class="status-link" @click="tab=PILOT_TAB.CONDITIONS">{{ $t("ui.publish_again") }}</button><button v-else-if="state.ticket.status==='matched'" class="status-link" @click="switchTab(PILOT_TAB.MY_RECRUITMENT)">{{ $t("ui.view_teammate") }}</button></view>
      <pilot-candidates :items="candidates.items" :total="candidates.total" :page="candidatePage" :recommended="recommended" :can-recommend="candidates.can_recommend" :busy="busy" :waiting="state.ticket?.status==='waiting'" :my-status="candidates.my_status" @refresh="loadCandidates" @mode="setCandidateMode" @edit="tab=PILOT_TAB.CONDITIONS" @invite="invite" @page="changePage" @skip="skipBatch">
       <template #status><view v-if="state.ticket?.status==='expired'" class="hall-expired" role="status"><view class="expired-ticker" :aria-label="$t(&quot;ui.your_listing_expired_publish_again_to_apply_for_a&quot;)" tabindex="0"><view class="expired-track" aria-hidden="true"><text>{{ $t("ui.your_listing_expired_publish_again_to_apply_for_a") }}</text><text>{{ $t("ui.your_listing_expired_publish_again_to_apply_for_a") }}</text></view></view><button class="expired-republish" @click="tab=PILOT_TAB.CONDITIONS">{{ $t("ui.publish_again") }}</button></view></template>
      </pilot-candidates>
    </view>
    <view v-if="tab===PILOT_TAB.MY_RECRUITMENT">
      <view v-if="state.ticket && state.squad" class="published-details-entry"><button class="btn-secondary" @click="detailsOpen=true">{{ $t("action.viewListing") }}</button></view>
      <view v-if="!state.ticket" class="panel-pilot empty"><view class="aside-title">{{ $t("ui.no_session_planned_yet") }}</view><view class="muted">{{ $t("ui.tell_teammates_what_you_want_to_play") }}</view><button class="btn-primary submit" @click="tab=PILOT_TAB.CONDITIONS">{{ $t("ui.set_up_your_listing") }}</button></view>
      <view v-else-if="!state.squad" class="panel-pilot empty queue-panel">
        <view class="queue-status"><text v-if="state.ticket.status==='waiting'" class="queue-live"/>{{state.ticket.status==='waiting'?$t("status.findingTeammate"):$t("ui.queue_ended")}}</view>
        <view v-if="state.ticket.status==='waiting'" class="queue-signal" aria-hidden="true"><view class="signal-ring"/><view class="signal-ring signal-ring-late"/><view class="signal-core"><text/><text/><text/></view></view>
        <view class="aside-title">{{state.ticket.status==='waiting'?$t("ui.waiting_for_a_compatible_player"):$t("ui.ready_for_another_session")}}</view>
        <view class="queue-hint">{{state.ticket.status==='waiting'?$t("ui.you_can_also_look_in_the_hall_listings_stay"):$t("ui.your_listing_has_ended_update_your_conditions_and_publish")}}</view>
        <view class="small">{{state.ticket.profile.region}} · {{profileSummary(state.ticket.profile)}}</view>
        <view class="queue-actions"><button class="btn-secondary submit" @click="detailsOpen=true">{{ $t("action.viewListing") }}</button><button v-if="state.ticket.status==='waiting'" class="btn-primary submit" @click="switchTab(PILOT_TAB.HALL)">{{ $t("ui.find_teammates") }}</button><button v-if="state.ticket.status==='waiting' && state.ticket.profile.public && !state.ticket.profile.is_demo" class="btn-primary submit share-recruitment" :disabled="busy" @click="growthRef?.makeShare()">{{ $t("ui.share_listing") }}</button><button v-if="activeTicket" class="btn-secondary submit" :disabled="busy" @click="act('cancel')">{{ $t("ui.leave_queue") }}</button><button v-else class="btn-primary submit" @click="tab=PILOT_TAB.CONDITIONS">{{ $t("ui.edit_conditions") }}</button></view>
      </view>
      <view v-else class="layout"><view><pilot-chat v-if="['ready','done'].includes(state.squad.status)" :key="state.squad.id" :squad-id="state.squad.id" :token="token"/><view class="panel-pilot"><view class="section-num">{{$t(statusLabel)}}</view><view class="aside-title">{{state.squad.status==='proposed'?$t("ui.confirm_the_agreement_before_entering_the_game"):$t("ui.team_ready_say_hello_before_you_play")}}</view><view v-if="state.squad.status==='proposed'" class="warning">{{ $t("ui.remaining") }} {{confirmRemaining}} {{ $t("ui.seconds_for_both_players_to_confirm_on_timeout_slots") }}</view><view class="members"><view v-for="m in state.squad.members" :key="m.id" class="member"><view class="avatar-pilot">{{m.profile.nickname.slice(0,1)}}</view><b>{{m.profile.nickname}}{{m.is_me?$t("ui.you"):''}}</b><view class="muted">{{m.profile.strength_score!==undefined?$t("ui.skill_score")+m.profile.strength_score:ranks[m.profile.rank-1]}}</view><view class="small">{{profileSummary(m.profile)}}<br/>{{$t(m.profile.voice)}}</view><view class="status-text">{{m.confirmed?$t("ui.confirmed"):$t("ui.awaiting_confirmation")}}</view><view v-if="['ready','done'].includes(state.squad.status) && m.profile.game_id">{{ $t("ui.game_id") }}{{m.profile.game_id}}</view></view></view>

      <view class="agreement"><b>{{ $t("ui.session_agreement") }}</b><view>{{ $t("ui.goal") }}{{$t(state.squad.agreement.goal)}}</view><view v-if="state.squad.agreement.schema_version===4">{{ $t("ui.map") }}{{$t(state.squad.agreement.map)}} · {{$t(state.squad.agreement.difficulty)}}<view v-if="state.squad.agreement.tasks.length">{{ $t("ui.shared_missions") }}{{state.squad.agreement.tasks.map(value=>$t(value)).join(' / ')}}</view></view><view v-else-if="state.squad.members[0].profile.strength_score!==undefined">{{profileSummary(state.squad.members[0].profile)}}</view><view v-else>{{ $t("ui.shared_budget") }}{{state.squad.agreement.budget_min}}–{{state.squad.agreement.budget_max}} {{ $t("ui.10k_player") }}</view><view>{{state.squad.members[0].profile.region}} · {{$t(state.squad.members[0].profile.slot)}}</view></view><view class="small">{{$t(state.squad.agreement.scope)}}</view>
      <button v-if="state.squad.status==='proposed'" class="btn-primary submit" :disabled="busy || myMember.confirmed" @click="act('confirm')">{{myMember.confirmed?$t("ui.confirmed_waiting_for_your_teammate"):$t("ui.accept_this_session_agreement")}}</button><view v-if="state.squad.status==='proposed'" class="reject-box"><view class="field-group">{{ $t("ui.not_a_fit_select_a_reason") }}<dark-select v-model="rejectReason" :options="DECLINE_REASONS.map(reason=>reason.value)" :option-labels="DECLINE_LABELS" :label="$t(&quot;ui.reason_for_declining&quot;)"/></view><button class="btn-secondary submit" :disabled="busy" @click="rejectProposal">{{ $t("ui.decline_keep_looking_reason_stays_private") }}</button></view><button v-if="['proposed','ready'].includes(state.squad.status) && !state.squad.feedback_submitted" class="btn-secondary submit" :disabled="busy" @click="cancelSquad">{{ $t("ui.cancel_team") }}</button><button v-if="['done','cancelled'].includes(state.squad.status) || state.squad.feedback_submitted" class="btn-primary submit" @click="tab=PILOT_TAB.CONDITIONS">{{ $t("ui.plan_another_session") }}</button>
      </view></view>
      <view class="panel-pilot" v-if="['ready','done'].includes(state.squad.status)"><text class="eyebrow">{{ $t("ui.private_session_feedback") }}</text><view class="aside-title">{{ $t("ui.would_you_team_up_again") }}</view><view v-if="state.squad.feedback_submitted" class="notice">{{ $t("ui.feedback_saved_thanks_for_helping_improve_matching") }}</view><view v-else><label>{{ $t("ui.did_you_actually_play_together") }}<view class="choices"><button :class="{chosen:review.played}" @click="review.played=true">{{ $t("ui.played_together") }}</button><button :class="{chosen:!review.played}" @click="review.played=false">{{ $t("ui.did_not_play") }}</button></view></label><view class="small" v-if="!review.played">{{ $t("ui.tell_us_why_you_did_not_play_together_to") }}</view><label v-for="item in reviewFields" :key="item.key">{{$t(item.label)}}<switch :checked="review[item.key]" @change="review[item.key]=$event.detail.value" color="#286952"/></label><label>{{ $t("ui.team_up_again") }}<view class="choices"><button v-for="o in againOptions" :key="o.value" :class="{chosen:review.again===o.value}" @click="review.again=o.value">{{$t(o.label)}}</button></view></label><label>{{ $t("ui.reason_optional") }}<textarea v-model="review.reason" maxlength="300" :placeholder="$t(&quot;ui.please_distinguish_skill_or_goal_mismatches_from_simply_losing&quot;)"/></label><button class="btn-primary submit" :disabled="busy || !review.again" @click="act('feedback',review)">{{ $t("ui.submit_feedback") }}</button></view></view>
      </view>
      <recent-squads :key="token" :token="token" :current-squad-id="state.squad?.id"/>
    </view>
    <published-recruitment v-if="detailsOpen && state.ticket" :ticket="state.ticket" @close="detailsOpen=false"/>
    <view class="footer">{{ $t("ui.player_match_operations") }}<button class="operations-entry" @click="growthRef?.openOperations()">{{ $t("ui.operations") }}</button><testing-tools :get-draft="getTestDraft" @import="applyTestImport" @simulation-start="startSimulation" @hall="switchTab(PILOT_TAB.HALL)"/></view>
  </view>
</template>
<script setup>
import {locale,t} from '../../i18n/index.js'
import LanguageSwitch from '../../components/language-switch.vue'
import { ref, reactive, computed, watch } from 'vue'
import {PILOT_TAB,PILOT_TABS,DECLINE_REASONS,DECLINE_LABELS} from '../../utils/pilot-navigation.js'
import { onShow, onHide, onUnload } from '@dcloudio/uni-app'
import GrowthTools from '../../components/growth-tools.vue'
import PilotCandidates from '../../components/pilot-candidates.vue'
import PilotChat from '../../components/pilot-chat.vue'
import RecentSquads from '../../components/recent-squads.vue'
import TestingTools from '../../components/testing-tools.vue'
import DarkSelect from '../../components/dark-select.vue'
import PublishedRecruitment from '../../components/published-recruitment.vue'
import RecruitmentWizard from '../../components/recruitment-wizard.vue'
import {loadPreferences} from '../../utils/pilot-preferences.js'
import { profileSummary } from '../../utils/recruitment.js'
import { sessionToken, setSessionToken, authRequest, ensureAnonymousSession } from '../../utils/pilot-session.js'
const growthRef=ref(null),wizardRef=ref(null),testImport=ref(null),wizardDraft=ref(null),detailsOpen=ref(false)
function applySharedMatch(value){applyState(value);tab.value=PILOT_TAB.MY_RECRUITMENT}
function applyActivity(segment){testImport.value={...getTestDraft(),...segment,slot:'',slot_explicit:false};tab.value=PILOT_TAB.CONDITIONS}
function getTestDraft(){return wizardRef.value?.getDraft()||state.value.ticket?.profile||loadPreferences(uni).values}
async function startSimulation(result){applyTestImport(result);applyState(result.state);tab.value=PILOT_TAB.HALL;candidatePage.value=0;recommended.value=false;await loadCandidates()}
function applyTestImport(result){if(result.token&&result.token!==token.value){state.value={};candidates.value={items:[],total:0,can_recommend:false};setSessionToken(result.token)}testImport.value={...result.profile};error.value='';tab.value=PILOT_TAB.CONDITIONS;refresh()}
const tab=ref(PILOT_TAB.CONDITIONS), busy=ref(false), error=ref(''), state=ref({}), config=ref({})
const candidates=ref({items:[],total:0,can_recommend:false}), recommended=ref(false), candidatePage=ref(0), rejectReason=ref(DECLINE_REASONS[0].value), clock=ref(Date.now())
let serverOffset=0, refreshing=false, tick=0, candidateLoadId=0
let timer=null, pageVisible=false
const browserVisible=()=>typeof document==='undefined'||document.visibilityState!=='hidden'
async function onVisibilityChange(){if(!pageVisible||!browserVisible()||!token.value)return;await refresh();if(tab.value===PILOT_TAB.HALL)await loadCandidates()}
const token=sessionToken
const ranks=['ui.bronze','ui.silver','ui.gold','ui.platinum','ui.diamond','ui.black_hawk','ui.pinnacle']
const review=reactive({played:true,again:'',goal_met:false,budget_met:false,skill_met:false,reason:''})
const reviewFields=[{key:'goal_met',label:'ui.followed_the_agreed_session_goal'},{key:'budget_met',label:'ui.brought_the_agreed_gear'},{key:'skill_met',label:'ui.skill_was_within_the_accepted_range'}], againOptions=[{value:'yes',label:'ui.yes'},{value:'unsure',label:'ui.not_sure'},{value:'no',label:'ui.no'}]
const activeTicket=computed(()=>['waiting','matched'].includes(state.value.ticket?.status))
const myMember=computed(()=>state.value.squad?.members.find(m=>m.is_me)||{})
const statusLabel=computed(()=>({proposed:'ui.teammate_found_awaiting_both_confirmations',ready:'ui.both_confirmed_add_each_other_in_game',done:'ui.session_completed',cancelled:'ui.session_cancelled'}[state.value.squad?.status]))
const confirmRemaining=computed(()=>Math.max(0,Math.ceil((Date.parse(state.value.squad?.deadline||'')-(clock.value+serverOffset))/1000))||0)
const request=authRequest
function applyState(value){clock.value=Date.now();state.value=value;config.value=value.config;if(value.server_now)serverOffset=Date.parse(value.server_now)-Date.now()}
async function refresh(){if(refreshing)return;refreshing=true;const identity=token.value;try{const value=await request('state');if(identity===token.value){applyState(value);error.value=''}}catch(e){if(identity===token.value)error.value=e.message}finally{refreshing=false;if(identity!==token.value)refresh()}}
async function loadCandidates(){const id=++candidateLoadId;try{const value=await request('candidates?recommended='+recommended.value+'&page='+candidatePage.value+'&listing_language='+(state.value.ticket?.profile?.listing_language||(locale.value==='en'?'en':'zh')));if(id===candidateLoadId)candidates.value=value}catch(e){if(id===candidateLoadId)error.value=e.message}}
function setCandidateMode(value){recommended.value=value;candidatePage.value=0;loadCandidates()}
function changePage(value){candidatePage.value=value;loadCandidates()}
async function invite(id){busy.value=true;error.value='';try{applyState(await request('invite',{candidate_id:id}));tab.value=PILOT_TAB.MY_RECRUITMENT}catch(e){error.value=e.message;await loadCandidates()}finally{busy.value=false}}
async function skipBatch(){busy.value=true;error.value='';try{await request('skip',{candidate_ids:candidates.value.items.map(c=>c.id)});candidatePage.value=0;await loadCandidates()}catch(e){error.value=e.message}finally{busy.value=false}}
async function switchTab(t){if(!PILOT_TABS.some(item=>item.id===t))return;tab.value=t;await refresh();if(t===PILOT_TAB.HALL)await loadCandidates()}
async function join(payload){busy.value=true;error.value='';try{applyState(await request('join',payload));Object.assign(review,{played:true,again:'',goal_met:false,budget_met:false,skill_met:false,reason:''});tab.value=state.value.squad?PILOT_TAB.MY_RECRUITMENT:payload.discovery==='browse'?PILOT_TAB.HALL:PILOT_TAB.MY_RECRUITMENT;if(tab.value===PILOT_TAB.HALL)await loadCandidates()}catch(e){error.value=e.message;uni.pageScrollTo({scrollTop:0,duration:200})}finally{busy.value=false}}
async function replaceRecruitment(payload){
 if(busy.value)return;const identity=token.value;busy.value=true;error.value=''
 try{const value=await request('replace',payload);if(identity!==token.value)return;applyState(value);Object.assign(review,{played:true,again:'',goal_met:false,budget_met:false,skill_met:false,reason:''});tab.value=PILOT_TAB.MY_RECRUITMENT}
 catch(e){if(identity===token.value){await refresh();if(identity===token.value)error.value=e.message}}
 finally{if(identity===token.value)busy.value=false}
}
async function act(action,data={}){busy.value=true;error.value='';try{applyState(await request(action,{...data,squad_id:state.value.squad?.id}));if(action==='reject'){tab.value=PILOT_TAB.HALL;candidatePage.value=0;await loadCandidates()}}catch(e){error.value=e.message}finally{busy.value=false}}
function rejectProposal(){act('reject',{reason:rejectReason.value})}
function cancelSquad(){uni.showModal({title:t('ui.cancel_this_team'),content:t('ui.you_will_leave_this_session_the_other_player_can'),confirmText:t('action.confirm'),cancelText:t('action.cancel'),success:r=>{if(r.confirm)act('cancel')}})}
async function init(){try{await ensureAnonymousSession();await refresh();}catch(e){error.value=e.message}clearInterval(timer);timer=setInterval(async()=>{if(!pageVisible||!browserVisible())return;clock.value=Date.now();if(!busy.value&&++tick%4===0){await refresh();if(tab.value===PILOT_TAB.HALL)await loadCandidates()}},1000)}

watch(token,async()=>{wizardDraft.value=null;detailsOpen.value=false;await refresh();if(tab.value===PILOT_TAB.HALL)await loadCandidates()})
onShow(()=>{uni.setNavigationBarTitle({title:t('app.title')});pageVisible=true;if(typeof document!=='undefined')document.addEventListener('visibilitychange',onVisibilityChange);init()});onHide(()=>{pageVisible=false;clearInterval(timer)});onUnload(()=>{pageVisible=false;clearInterval(timer);if(typeof document!=='undefined')document.removeEventListener('visibilitychange',onVisibilityChange)})
</script>
